I do not think it should be exposed in the main API, but it's probably OK to do it in the text server code (I only did one method as example):

```diff
diff --git a/servers/text/text_server.h b/servers/text/text_server.h
index 311b2d2243..d4e963cbcb 100644
--- a/servers/text/text_server.h
+++ b/servers/text/text_server.h
@@ -537,8 +537,9 @@ public:
 	bool shaped_text_has_visible_chars(const RID &p_shaped) const;

 	virtual const Glyph *shaped_text_get_glyphs(const RID &p_shaped) const = 0;
 	TypedArray<Dictionary> _shaped_text_get_glyphs_wrapper(const RID &p_shaped) const;
+	GDExtensionPtr<const Glyph> _shaped_text_get_glyphs_gde_wrapper(const RID &p_shaped) const;
 	virtual const Glyph *shaped_text_sort_logical(const RID &p_shaped) = 0;
 	TypedArray<Dictionary> _shaped_text_sort_logical_wrapper(const RID &p_shaped);
 	virtual int64_t shaped_text_get_glyph_count(const RID &p_shaped) const = 0;

diff --git a/servers/text/text_server.cpp b/servers/text/text_server.cpp
index c58f46ee06..5341e49ad4 100644
--- a/servers/text/text_server.cpp
+++ b/servers/text/text_server.cpp
@@ -479,8 +479,9 @@ void TextServer::_bind_methods() {
 	ClassDB::bind_method(D_METHOD("shaped_text_is_ready", "shaped"), &TextServer::shaped_text_is_ready);
 	ClassDB::bind_method(D_METHOD("shaped_text_has_visible_chars", "shaped"), &TextServer::shaped_text_has_visible_chars);

 	ClassDB::bind_method(D_METHOD("shaped_text_get_glyphs", "shaped"), &TextServer::_shaped_text_get_glyphs_wrapper);
+	ClassDB::bind_method(D_METHOD("shaped_text_get_glyphs_ptr", "shaped"), &TextServer::_shaped_text_get_glyphs_gde_wrapper);
 	ClassDB::bind_method(D_METHOD("shaped_text_sort_logical", "shaped"), &TextServer::_shaped_text_sort_logical_wrapper);
 	ClassDB::bind_method(D_METHOD("shaped_text_get_glyph_count", "shaped"), &TextServer::shaped_text_get_glyph_count);

 	ClassDB::bind_method(D_METHOD("shaped_text_get_range", "shaped"), &TextServer::shaped_text_get_range);
@@ -2328,8 +2329,12 @@ TypedArray<Dictionary> TextServer::_shaped_text_get_glyphs_wrapper(const RID &p_

 	return ret;
 }

+GDExtensionPtr<const Glyph> TextServer::_shaped_text_get_glyphs_gde_wrapper(const RID &p_shaped) const {
+	return GDExtensionPtr(shaped_text_get_glyphs(p_shaped));
+}
+
 TypedArray<Dictionary> TextServer::_shaped_text_sort_logical_wrapper(const RID &p_shaped) {
 	Array ret;

 	const Glyph *glyphs = shaped_text_sort_logical(p_shaped);
```

